questions.starter:
// HTML on the page:
// <button id="greet-btn">Greet</button>
// <p id="output">Waiting...</p>

// 1. Add click event listener to the button

// 2. Inside the handler: update output textContent

// 3. Inside the handler: add 'active' class to the button

questions.solution:
const btn = document.getElementById('greet-btn');
const output = document.getElementById('output');

btn.addEventListener('click', function () {
  output.textContent = 'Hello, Amara!';
  btn.classList.add('active');
});

questions.starter:
// HTML on the page:
// <form id="name-form">
//   <input type="text" id="name-input">
//   <button type="submit">Add</button>
// </form>
// <ul id="name-list"></ul>

// Add submit event listener to the form
// preventDefault, get value, createElement li, appendChild, clear input

questions.solution:
const form = document.getElementById('name-form');
const input = document.getElementById('name-input');
const list = document.getElementById('name-list');

form.addEventListener('submit', function (e) {
  e.preventDefault();
  const li = document.createElement('li');
  li.textContent = input.value;
  list.appendChild(li);
  input.value = '';
});

questions.starter:
// HTML on the page:
// <input type="text" id="search-box" placeholder="Type and press Enter">
// <p id="result"></p>

// Add keydown event listener
// If Enter: show search text in result
// If Escape: clear input and result

questions.solution:
const searchBox = document.getElementById('search-box');
const result = document.getElementById('result');

searchBox.addEventListener('keydown', function (e) {
  if (e.key === 'Enter') {
    result.textContent = 'Searching for: ' + searchBox.value;
  }
  if (e.key === 'Escape') {
    searchBox.value = '';
    result.textContent = '';
  }
});

questions.starter:
// HTML on the page:
// <div id="container"></div>

// 1. Create a div with class 'card' and textContent 'New Card'
// 2. Create a button with textContent '×' and class 'delete-btn'
// 3. Add click listener to button — remove parent element
// 4. Append button to div, then div to container

questions.solution:
const container = document.getElementById('container');

const card = document.createElement('div');
card.classList.add('card');
card.textContent = 'New Card';

const deleteBtn = document.createElement('button');
deleteBtn.textContent = '×';
deleteBtn.classList.add('delete-btn');

deleteBtn.addEventListener('click', function () {
  card.remove();
});

card.appendChild(deleteBtn);
container.appendChild(card);

questions.starter:
// HTML on the page:
// <button id="toggle-btn">Show Panel</button>
// <div id="panel" class="panel">Panel content here</div>

// Add click listener to toggle-btn
// Toggle 'visible' class on panel
// Update button text based on panel state

questions.solution:
const toggleBtn = document.getElementById('toggle-btn');
const panel = document.getElementById('panel');

toggleBtn.addEventListener('click', function () {
  panel.classList.toggle('visible');
  if (panel.classList.contains('visible')) {
    toggleBtn.textContent = 'Hide Panel';
  } else {
    toggleBtn.textContent = 'Show Panel';
  }
});

questions.starter:
// HTML on the page:
// <input type="text" id="char-input" placeholder="Type something...">
// <p id="char-count">0 characters</p>

// Add input event listener
// Update character count on each keystroke
// Add/remove 'warning' class based on length

questions.solution:
const charInput = document.getElementById('char-input');
const charCount = document.getElementById('char-count');

charInput.addEventListener('input', function () {
  const length = charInput.value.length;
  charCount.textContent = length + ' characters';
  if (length > 20) {
    charCount.classList.add('warning');
  } else {
    charCount.classList.remove('warning');
  }
});

questions.starter:
// HTML on the page:
// <form id="login-form">
//   <input type="email" id="email-input">
//   <input type="password" id="password-input">
//   <button type="submit">Login</button>
// </form>
// <p id="form-error"></p>

// Add submit listener with validation logic

questions.solution:
const form = document.getElementById('login-form');
const emailInput = document.getElementById('email-input');
const passwordInput = document.getElementById('password-input');
const formError = document.getElementById('form-error');

form.addEventListener('submit', function (e) {
  e.preventDefault();
  const email = emailInput.value;
  const password = passwordInput.value;

  if (email === '' || password === '') {
    formError.textContent = 'All fields are required';
    formError.classList.add('error');
    formError.classList.remove('success');
  } else {
    formError.textContent = 'Login successful!';
    formError.classList.remove('error');
    formError.classList.add('success');
  }
});

