questions.starter:
// HTML on the page:
// <ul id="task-list">
//   <li>Buy groceries <button class="delete-btn">×</button></li>
//   <li>Write code <button class="delete-btn">×</button></li>
//   <li>Read book <button class="delete-btn">×</button></li>
// </ul>

// Add ONE click listener to the ul (event delegation)
// Check if e.target has class 'delete-btn'
// If yes: log and remove the parent li

questions.solution:
const taskList = document.getElementById('task-list');

taskList.addEventListener('click', function (e) {
  if (e.target.classList.contains('delete-btn')) {
    const li = e.target.parentElement;
    console.log('Deleted: ' + li.textContent);
    li.remove();
  }
});

questions.starter:
// HTML on the page:
// <button id="add-btn">Add Notification</button>
// <div id="notification-area"></div>

// Track count starting at 0
// Click handler: increment count, create notification + dismiss button, append

questions.solution:
const addBtn = document.getElementById('add-btn');
const area = document.getElementById('notification-area');
let count = 0;

addBtn.addEventListener('click', function () {
  count++;
  const notification = document.createElement('div');
  notification.classList.add('notification');
  notification.textContent = 'Notification ' + count;

  const dismissBtn = document.createElement('button');
  dismissBtn.textContent = 'Dismiss';
  dismissBtn.addEventListener('click', function () {
    notification.remove();
  });

  notification.appendChild(dismissBtn);
  area.appendChild(notification);
});
